const rows = $input.all().map(i => i.json);

function extraerMonto(msg) {
  if (!msg) return null;
  const m = msg.match(/\$\s?([\d.]+)/);
  return m ? parseInt(m[1].replace(/\./g, ''), 10) : null;
}

const UNIDADES_POR_MONTO = { 35000: '1 unidad', 45000: '2 unidades', 60000: '3 unidades' };

function fmtFecha(iso) {
  return new Date(iso).toLocaleString('es-AR', { timeZone: 'America/Argentina/Buenos_Aires', day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit' });
}

const lineas = rows.map((r, i) => {
  const numero = r.session_id.split('@')[0];
  const monto = extraerMonto(r.payment_msg);
  const detalle = monto ? `$${monto.toLocaleString('es-AR')} (${UNIDADES_POR_MONTO[monto] || 'monto no estandar'})` : 'monto no quedo claro, preguntale';
  return `${i + 1}. +${numero} - ${detalle} - ultima actividad: ${fmtFecha(r.last_at)}`;
});

let text = 'Hola mi amor \u{1FA77} No olvides cuanto te amo, hasta el gzn.\n\n';
if (lineas.length === 0) {
  text += 'Hoy no hay clientes pendientes de seguimiento, todos al dia \u{1F389}';
} else {
  text += `Estos son los clientes con pedido pendiente de seguimiento (${lineas.length}):\n\n` + lineas.join('\n');
}

return [{ json: { text } }];
